CREATE DATABASE IF NOT EXISTS asmraudio CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE asmraudio;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,display_name VARCHAR(120) NOT NULL DEFAULT 'Administrator',role ENUM('admin','editor') NOT NULL DEFAULT 'admin',failed_attempts INT NOT NULL DEFAULT 0,locked_until DATETIME NULL,last_login_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(120) UNIQUE NOT NULL,parent_id INT NULL,description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_category_parent FOREIGN KEY(parent_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE articles(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,slug VARCHAR(255) UNIQUE NOT NULL,excerpt TEXT,content LONGTEXT NOT NULL,category VARCHAR(100),subcategory VARCHAR(100),featured_image VARCHAR(500) NULL,status ENUM('draft','scheduled','published','archived') DEFAULT 'draft',author VARCHAR(120) DEFAULT 'ASMR Audio Online',focus_keyword VARCHAR(190),meta_title VARCHAR(255),meta_description TEXT,canonical_url VARCHAR(500),schema_type VARCHAR(80) DEFAULT 'Article',faq_json JSON NULL,published_at DATETIME NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,views INT DEFAULT 0,featured TINYINT DEFAULT 0,noindex TINYINT DEFAULT 0,INDEX(status),INDEX(category));
CREATE TABLE subscribers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120),email VARCHAR(190) UNIQUE NOT NULL,consent TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE contact_messages(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,subject VARCHAR(255) NOT NULL,message TEXT NOT NULL,status ENUM('new','read','archived') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(status),INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audio_tracks(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,slug VARCHAR(255) UNIQUE NOT NULL,description TEXT,category VARCHAR(120),trigger_type VARCHAR(120),audio_url VARCHAR(500) NOT NULL,cover_image VARCHAR(500),duration_seconds INT UNSIGNED DEFAULT 0,license_text TEXT,downloadable TINYINT DEFAULT 0,status ENUM('draft','published','archived') DEFAULT 'draft',plays INT UNSIGNED DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(status),INDEX(category)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE creators(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,slug VARCHAR(190) UNIQUE NOT NULL,profile_image VARCHAR(500),country VARCHAR(120),language VARCHAR(120),specialties VARCHAR(500),biography TEXT,youtube_url VARCHAR(500),website_url VARCHAR(500),social_links_json JSON NULL,video_ids_json JSON NULL,status ENUM('draft','published','archived') DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY,product_name VARCHAR(255) NOT NULL,slug VARCHAR(255) UNIQUE,brand VARCHAR(120),category VARCHAR(120),image VARCHAR(500),short_description TEXT,best_for VARCHAR(190),price_text VARCHAR(120),rating DECIMAL(3,2) NULL,affiliate_url TEXT,merchant VARCHAR(100),button_text VARCHAR(80) DEFAULT 'View product',status ENUM('draft','published') DEFAULT 'draft',featured TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(status),INDEX(category));
CREATE TABLE affiliate_clicks(id BIGINT AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,referrer VARCHAR(500) NULL,ip_hash CHAR(64) NULL,user_agent VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(product_id),INDEX(created_at),CONSTRAINT fk_affiliate_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE page_views(id BIGINT AUTO_INCREMENT PRIMARY KEY,path VARCHAR(500) NOT NULL,ip_hash CHAR(64) NULL,referrer VARCHAR(500) NULL,user_agent VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(path),INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE comments(id BIGINT AUTO_INCREMENT PRIMARY KEY,article_id INT NOT NULL,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,body TEXT NOT NULL,status ENUM('pending','approved','spam','deleted') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(article_id,status),CONSTRAINT fk_comment_article FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE advertisements(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,slot VARCHAR(80) NOT NULL,html_code TEXT NOT NULL,width SMALLINT UNSIGNED,height SMALLINT UNSIGNED,status ENUM('inactive','active') DEFAULT 'inactive',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(slot,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE settings(setting_key VARCHAR(120) PRIMARY KEY,setting_value TEXT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE admin_activity(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(120) NOT NULL,details VARCHAR(500) NULL,ip_hash CHAR(64) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),INDEX(created_at),CONSTRAINT fk_activity_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE article_categories(article_id INT NOT NULL,category_id INT NOT NULL,PRIMARY KEY(article_id,category_id),CONSTRAINT fk_ac_article FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE,CONSTRAINT fk_ac_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE redirects(id INT AUTO_INCREMENT PRIMARY KEY,source_path VARCHAR(500) UNIQUE NOT NULL,target_url VARCHAR(500) NOT NULL,status_code SMALLINT UNSIGNED NOT NULL DEFAULT 301,active TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO articles(title,slug,excerpt,content,category,status,published_at) VALUES ('What Is ASMR? A Complete Beginner’s Guide','what-is-asmr','Learn how ASMR works and how to explore it safely.','<h2>What is ASMR?</h2><p>ASMR is a relaxing response some people experience from gentle sounds, visuals or personal attention.</p><h2>Popular triggers</h2><p>Whispering, tapping, brushing and rain sounds are common starting points.</p>','ASMR Guides','published',NOW());
